import androidx.lifecycle.ViewModel
import androidx.lifecycle.viewModelScope
import com.jumblemint.cows.data.model.Pasture
import com.jumblemint.cows.data.repository.CattleRepository
import kotlinx.coroutines.flow.MutableStateFlow
import kotlinx.coroutines.flow.StateFlow
import kotlinx.coroutines.flow.asStateFlow
import kotlinx.coroutines.flow.first
import kotlinx.coroutines.launch

class PasturesViewModel(
 private val repository: CattleRepository
) : ViewModel() {

 private val _uiState = MutableStateFlow(PasturesUiState())
 val uiState: StateFlow<PasturesUiState> = _uiState.asStateFlow()

 init {
 loadPastures()
 }

 private fun loadPastures() {
 viewModelScope.launch {
 try {
 // Get current pastures
 val pastures = repository.getAllPastures().first()

 // Load cow counts for each pasture
 val cowCounts = mutableMapOf<Long, Int>()
 pastures.forEach { pasture ->
 val cows = repository.getCowsByPasture(pasture.id).first()
 cowCounts[pasture.id] = cows.size
 }

 _uiState.value = _uiState.value.copy(
 pastures = pastures,
 pasturesCowCount = cowCounts,
 isLoading = false
 )
 } catch (e: Exception) {
 _uiState.value = _uiState.value.copy(
 error = e.message,
 isLoading = false
 )
 }
 }
 }

 fun addPasture(name: String, acreage: Double?) {
 viewModelScope.launch {
 try {
 val pasture = Pasture(
 name = name,
 acreage = acreage
 )
 repository.insertPasture(pasture)
 } catch (e: Exception) {
 _uiState.value = _uiState.value.copy(error = e.message)
 }
 }
 }
}

data class PasturesUiState(
 val pastures: List<Pasture> = emptyList(),
 val pasturesCowCount: Map<Long, Int> = emptyMap(),
 val isLoading: Boolean = true,
 val error: String? = null
)","language":"kotlin"},"codebaseEnabled":true},"createdAt":1756091028575,"isInternal":false,"rawContent":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"I still can't choose a date for birthdate when entering cow."}]},{"type":"paragraph"},{"type":"paragraph","content":[{"type":"text","text":"The pastures screen is working, but i want it to list total head, as well as how many cows, bulls and calves on the card, then be able to click the pasture to see see a list of cows, either on a new screen or on the cows screen filtered by pasture"}]}]},"autoAppliedRules":[]},{"id":"00b7e7d1-75d0-4830-8513-d462ec117ada","role":"assistant","content":[{"type":"text","text":"Let me fix the date picker issue first, then enhance the pastures functionality.

