+
+@Composable
+fun SampleDataDialog(
+ isSampleDataInstalled: Boolean,
+ onDismiss: () -> Unit,
+ onInstall: () -> Unit,
+ onRemove: () -> Unit
+) {
+ AlertDialog(
+ onDismissRequest = onDismiss,
+ title = { 
+ Text(if (isSampleDataInstalled) "Remove Sample Data" else "Add Sample Data") 
+ },
+ text = {
+ Column {
+ Text(
+ text = if (isSampleDataInstalled) {
+ "This will remove all sample cattle, pastures, and activities from your database. This action cannot be undone."
+ } else {
+ "This will add sample cattle, pastures, and activities to help you explore the app's features. You can remove this data later."
+ },
+ style = MaterialTheme.typography.bodyMedium
+ )
+ 
+ if (!isSampleDataInstalled) {
+ Spacer(modifier = Modifier.height(16.dp))
+ Text(
+ text = "Sample data includes:",
+ style = MaterialTheme.typography.bodyMedium,
+ fontWeight = FontWeight.Medium
+ )
+ Spacer(modifier = Modifier.height(8.dp))
+ Text(
+ text = "• 10 sample cattle with various ages and genders\n" +
+ "• 3 pastures with different acreages\n" +
+ "• Sample activities like births, moves, and sales",
+ style = MaterialTheme.typography.bodySmall,
+ color = MaterialTheme.colorScheme.onSurfaceVariant
+ )
+ }
+ }
+ },
+ confirmButton = {
+ Button(
+ onClick = if (isSampleDataInstalled) onRemove else onInstall,
+ colors = if (isSampleDataInstalled) {
+ ButtonDefaults.buttonColors(
+ containerColor = MaterialTheme.colorScheme.error
+ )
+ } else {
+ ButtonDefaults.buttonColors()
+ }
+ ) {
+ Text(if (isSampleDataInstalled) "Remove" else "Install")
+ }
+ },
+ dismissButton = {
+ TextButton(onClick = onDismiss) {
+ Text("Cancel")
+ }
+ }
+ )
+}
+
+@Composable
+fun DeleteAllDataDialog(
+ onDismiss: () -> Unit,
+ onConfirm: () -> Unit
+) {
+ AlertDialog(
+ onDismissRequest = onDismiss,
+ title = { 
+ Text(
+ "Delete All Data",
+ color = MaterialTheme.colorScheme.error
+ ) 
+ },
+ text = {
+ Column {
+ Icon(
+ imageVector = Icons.Default.Warning,
+ contentDescription = null,
+ tint = MaterialTheme.colorScheme.error,
+ modifier = Modifier
+ .size(48.dp)
+ .align(Alignment.CenterHorizontally)
+ )
+ Spacer(modifier = Modifier.height(16.dp))
+ Text(
+ text = "This will permanently delete ALL data from your app:",
+ style = MaterialTheme.typography.bodyMedium,
+ fontWeight = FontWeight.Medium
+ )
+ Spacer(modifier = Modifier.height(8.dp))
+ Text(
+ text = "• All cattle records\n" +
+ "• All pasture information\n" +
+ "• All activity history\n" +
+ "• All custom settings",
+ style = MaterialTheme.typography.bodySmall,
+ color = MaterialTheme.colorScheme.onSurfaceVariant
+ )
+ Spacer(modifier = Modifier.height(16.dp))
+ Text(
+ text = "This action cannot be undone!",
+ style = MaterialTheme.typography.bodyMedium,
+ fontWeight = FontWeight.Bold,
+ color = MaterialTheme.colorScheme.error
+ )
+ }
+ },
+ confirmButton = {
+ Button(
+ onClick = onConfirm,
+ colors = ButtonDefaults.buttonColors(
+ containerColor = MaterialTheme.colorScheme.error
+ )
+ ) {
+ Text("Delete All")
+ }
+ },
+ dismissButton = {
+ TextButton(onClick = onDismiss) {
+ Text("Cancel")
+ }
+ }
+ )
+}","refToolCallId":"toolu_0196pZfc6AxzketHryu6nZVj"},{"type":"text","text":"Perfect! I've successfully added the missing composables to the SettingsScreen.kt file. Let me also check if we:"},{"type":"toolCall","toolCallId":"toolu_01KTXqFGYEcvDmSyxDVAP6Lv","statusText":"Viewed file (from the beginning up to line 40)","status":"SUCCESS","context":{"files":[{"path":"app/src/main/java/com/jumblemint/cows/ui/screens/settings/SettingsScreen.kt","fsPath":"C:/Users/jeepi/AndroidStudioProjects/cows/app/src/main/java/com/jumblemint/cows/ui/screens/settings/SettingsScreen.kt"}]},"isHidden":false},{"type":"text","text":" need to add any missing imports for the new componentsI need to add the missing import for `size` modifier. Let me add it:"},{"type":"toolCall","toolCallId":"toolu_01Cm6ZpBHxknAW2PbaeeoWEJ","title":"","statusText":"Edit operation cancelled: The new text is identical to the original text.","status":"WARNING","isHidden":false},{"type":"text","text":"Actually, the `size` modifier should already be available through the `androidx.compose.foundation.layout.*` import. Let me check if there are any compilation issues by building the project:"},{"type":"toolCall","toolCallId":"toolu_01ANRTbMTywgrXUCgqjn1zc4","status":"IN_PROGRESS","isHidden":true,"localResult":"{"status":"ERROR","exitCode":1,"output":"\u001b[?9001h\u001b[?1004h\u001b[?25l\u001b[2J\u001b[m\u001b[38;5;9m\u001b[HC:\\Users\\jeepi\\AppData\\Local\\Temp\\Zencoder-f3dd1938-c98b-4dc2-ae59-bfa5f4c42948.ps1 : File \r\nC:\\Users\\jeepi\\AppData\\Local\\Temp\\Zencoder-f3dd1938-c98b-4dc2-ae59-bfa5f4c42948.ps1 cannot be loaded because running \r\nscripts is disabled on this system. For more information, see about_Execution_Policies at \r\nhttps:/go.microsoft.com/fwlink/?LinkID=135170.\r\nAt line:1 char:1\r\n+ C:\\Users\\jeepi\\AppData\\Local\\Temp\\Zencoder-f3dd1938-c98b-4dc2-ae59-bf ...\r\n+ ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~\r\n + CategoryInfo : SecurityError: (:) [], PSSecurity