import android.content.Context
import androidx.room.Database
import androidx.room.Room
import androidx.room.RoomDatabase
import androidx.room.TypeConverters
import androidx.room.migration.Migration
import androidx.sqlite.db.SupportSQLiteDatabase
import com.jumblemint.cows.data.dao.*
import com.jumblemint.cows.data.model.*
// Remove java.util.concurrent.Executors import if DatabaseCallback doesn't need it explicitly passed anymore

@Database(
 entities = [Cow::class, Pasture::class, Activity::class, Settings::class, Note::class], // Note::class is present
 version = 2, // Assuming version 2 is appropriate for adding Note table.
 exportSchema = false
)
@TypeConverters(Converters::class)
abstract class CattleDatabase : RoomDatabase() {

 abstract fun cowDao(): CowDao
 abstract fun pastureDao(): PastureDao
 abstract fun activityDao(): ActivityDao
 abstract fun settingsDao(): SettingsDao
 abstract fun noteDao(): NoteDao // noteDao() is present

 companion object {
 @Volatile
 private var INSTANCE: CattleDatabase? = null

 val MIGRATION_1_2 = object : Migration(1, 2) {
 override fun migrate(db: SupportSQLiteDatabase) {
 db.execSQL("ALTER TABLE cows ADD COLUMN isWatched INTEGER NOT NULL DEFAULT 0")
 // Lines for creating notes table are NOW UNCOMMENTED:
 db.execSQL("CREATE TABLE IF NOT EXISTS `notes` (`id` INTEGER PRIMARY KEY AUTOINCREMENT NOT NULL, `cowId` TEXT NOT NULL, `text` TEXT NOT NULL, `timestamp` INTEGER NOT NULL, FOREIGN KEY(`cowId`) REFERENCES `cows`(`id`) ON UPDATE NO ACTION ON DELETE CASCADE)")
 db.execSQL("CREATE INDEX IF NOT EXISTS `index_notes_cowId` ON `notes` (`cowId`)")
 }
 }

 fun getDatabase(context: Context): CattleDatabase {
 return INSTANCE ?: synchronized(this) {
 val instance = Room.databaseBuilder(
 context.applicationContext,
 CattleDatabase::class.java,
 "cattle_database"
 )
 .addMigrations(MIGRATION_1_2) // This migration is now correctly defined
 .addCallback(DatabaseCallback())
 .build()
 INSTANCE = instance
 instance
 }
 }
 }
}
