@Composable
fun SettingsCard(
 title: String,
 subtitle: String,
 icon: androidx.compose.ui.graphics.vector.ImageVector,
 onClick: () -> Unit
) {
 Card(
 onClick = onClick,
 modifier = Modifier.fillMaxWidth()
 ) {
 Row(
 modifier = Modifier.padding(16.dp),
 verticalAlignment = Alignment.CenterVertically
 ) {
 Icon(
 imageVector = icon,
 contentDescription = null,
 tint = MaterialTheme.colorScheme.primary
 )
 Spacer(modifier = Modifier.width(16.dp))
 Column(modifier = Modifier.weight(1f)) {
 Text(
 text = title,
 style = MaterialTheme.typography.titleSmall,
 fontWeight = FontWeight.Medium
 )
 Text(
 text = subtitle,
 style = MaterialTheme.typography.bodySmall,
 color = MaterialTheme.colorScheme.onSurfaceVariant
 )
 }
 Icon(
 imageVector = Icons.Default.KeyboardArrowRight,
 contentDescription = null,
 tint = MaterialTheme.colorScheme.onSurfaceVariant
 )
 }
 }
}

@Composable
fun TagColorsDialog(
 currentColors: List<String>,
 onDismiss: () -> Unit,
 onSave: (List<String>) -> Unit
) {
 var colors by remember { mutableStateOf(currentColors.joinToString(", ")) }

 AlertDialog(
 onDismissRequest = onDismiss,
 title = { Text("Tag Colors") },
 text = {
 Column {
 Text(
 text = "Enter tag colors separated by commas:",
 style = MaterialTheme.typography.bodyMedium
 )
 Spacer(modifier = Modifier.height(8.dp))
 OutlinedTextField(
 value = colors,
 onValueChange = { colors = it },
 label = { Text("Colors") },
 placeholder = { Text("Red, Blue, Green, Yellow...") },
 modifier = Modifier.fillMaxWidth(),
 minLines = 3
 )
 }
 },
 confirmButton = {
 TextButton(
 onClick = {
 val colorList = colors.split(",").map { it.trim() }.filter { it.isNotBlank() }
 onSave(colorList)
 }
 ) {
 Text("Save")
 }
 },
 dismissButton = {
 TextButton(onClick = onDismiss) {
 Text("Cancel")
 }
 }
 )
}

@Composable
fun ActivityTypesDialog(
 currentTypes: List<String>,
 onDismiss: () -> Unit,
 onSave: (List<String>) -> Unit
) {
