 OutlinedTextField(
 value = types,
 onValueChange = { types = it },
 label = { Text("Activity Types") },
 placeholder = { Text("MOVED, WEANED, SOLD, DECEASED...") },
 modifier = Modifier.fillMaxWidth(),
 minLines = 3
 )
 }
 },
 confirmButton = {
