+%0A%0D%0A // Sample data management%0D%0A suspend fun isSampleDataInstalled(): Boolean %7B%0D%0A return getSettingByKey(SettingsKeys.SAMPLE_DATA_INSTALLED)?.value == %22true%22%0D%0A %7D%0D%0A%0D%0A suspend fun installSampleData() %7B%0D%0A if (isSampleDataInstalled()) return%0D%0A%0D%0A // Create sample pastures%0D%0A val pastureIds = createSamplePastures()%0D%0A %0D%0A // Create sample cows%0D%0A val cowIds = createSampleCows(pastureIds)%0D%0A %0D%0A // Create sample activities%0D%0A createSampleActivities(cowIds, pastureIds)%0D%0A %0D%0A // Create sample notes%0D%0A createSampleNotes()%0D%0A %0D%0A // Mark sample data as installed%0D%0A insertOrUpdateSetting(%0D%0A Settings(%0D%0A SettingsKeys.SAMPLE_DATA_INSTALLED,%0D%0A %22true%22%0D%0A )%0D%0A )%0D%0A %7D%0D%0A%0D%0A private suspend fun createSamplePastures(): List%3CString%3E %7B%0D%0A val pastures = listOf(%0D%0A Pasture(%0D%0A id = %22sample-pasture-1%22,%0D%0A name = %22North Field%22,%0D%0A description = %22Large pasture with good grass coverage%22,%0D%0A sizeAcres = 25.5%0D%0A ),%0D%0A Pasture(%0D%0A id = %22sample-pasture-2%22, %0D%0A name = %22South Meadow%22,%0D%0A description = %22Rolling hills with creek access%22,%0D%0A sizeAcres = 18.0%0D%0A ),%0D%0A Pasture(%0D%0A id = %22sample-pasture-3%22,%0D%0A name = %22East Paddock%22,%0D%0A description = %22Smaller paddock for breeding stock%22,%0D%0A sizeAcres = 8.5%0D%0A ),%0D%0A Pasture(%0D%0A id = %22sample-pasture-4%22,%0D%0A name = %22West Lot%22,%0D%0A description = %22Holding area near barn%22,%0D%0A sizeAcres = 5.0%0D%0A )%0D%0A )%0D%0A %0D%0A pastures.forEach %7B insertPasture(it) %7D%0D%0A return pastures.map %7B it.id %7D%0D%0A %7D%0D%0A%0D%0A private suspend fun createSampleCows(pastureIds: List%3CString%3E): List%3CLong%3E %7B%0D%0A val baseDate = LocalDate.now().minusYears(2)%0D%0A val cows = listOf(%0D%0A // Bulls%0D%0A Cow(%0D%0A name = %22Thunder%22,%0D%0A tagNumber = %22B001%22,%0D%0A tagColor = %22Red%22,%0D%0A birthDate = baseDate.minusYears(3),%0D%0A gender = Gender.MALE,%0D%0A classification = Classification.BULL,%0D%0A colorMarkings = %22Black with white face%22,%0D%0A pastureId = pastureIds%5B2%5D, // East Paddock%0D%0A status = Status.ACTIVE%0D%0A ),%0D%0A Cow(%0D%0A name = %22Storm%22,%0D%0A tagNumber = %22B002%22, %0D%0A tagColor = %22Blue%22,%0D%0A birthDate = baseDate.minusYears(2),%0D%0A gender = Gender.MALE,%0D%0A classification = Classification.BULL,%0D%0A colorMarkings = %22Red Angus%22,%0D%0A pastureId = pastureIds%5B2%5D, // East Paddock%0D%0A status = Status.ACTIVE%0D%0A ),%0D%0A %0D%0A // Cows%0D%0A Cow(%0D%0A name = %22Bessie%22,%0D%0A tagNumber = %22C001%22,%0D%0A tagColor = %22Yellow%22,%0D%0A birthDate = baseDate.minusYears(4),%0D%0A gender = Gender.FEMALE,%0D%0A classification = Classification.COW,%0D%0A colorMarkings = %22Holstein black and white%22,%0D%0A pastureId = pastureIds%5B0%5D, // North Field%0D%0A status = Status.ACTIVE,%0D%0A isWatched = true%0D%0A ),%0D%0A Cow(%0D%0A name = %22Daisy%22,%0D%0A tagNumber = %22C002%22,%0D%0A tagColor = %22Green%22,%0D%0A birthDate = baseDate.minusYears(3),%0D%0A gender = Gender.FEMALE,%0D%0A classification = Classification.COW,%0D%0A colorMarkings = %22Brown Jersey%22,%0D%0A pastureId = pastureIds%5B0%5D, // North Field%0D%0A status = Status.ACTIVE%0D%0A ),%0D%0A Cow(%0D%0A name = %22Rosie%22,%0D%0A tagNumber = %22C003%22,%0D%0A tagColor = %22Purple%22,%0D%0A birthDate = baseDate.minusYears(5),%0D%0A gender = Gender.FEMALE,%0D%0A classification = Classification.COW,%0D%0A colorMarkings = %22Black Angus%22,%0D%0A pastureId = pastureIds%5B1%5D, // South Meadow%0D%0A status = Status.ACTIVE,%0D%0A isWatched = true%0D%0A ),%0D%0A %0D%0A // Heifers%0D%0A Cow(%0D%0A name = %22Luna%22,%0D%0A tagNumber = %22H001%22,%0D%0A tagColor = %22Pink%22,%0D%0A birthDate = baseDate.minusYears(1),%0D%0A gender = Gender.FEMALE,%0D%0A classification = Classification.HEIFER,%0D%0A colorMarkings = %22Red with white markings%22,%0D%0A pastureId = pastureIds%5B1%5D, // South Meadow%0D%0A status = Status.ACTIVE%0D%0A ),%0D%0A Cow(%0D%0A name = %22Star%22,%0D%0A tagNumber = %22H002%22,%0D%0A tagColor = %22Orange%22,%0D%0A birthDate = baseDate.minusMonths(18),%0D%0A gender = Gender.FEMALE,%0D%0A classification = Classification.HEIFER,%0D%0A colorMarkings = %22Charolais cream colored%22,%0D%0A pastureId = pastureIds%5B1%5D, // South Meadow%0D%0A status = Status.ACTIVE%0D%0A ),%0D%0A %0D%0A // Steers%0D%0A Cow(%0D%0A name = %22Max%22,%0D%0A tagNumber = %22S001%22,%0D%0A tagColor = %22White%22,%0D%0A birthDate = baseDate.minusMonths(20),%0D%0A gender = Gender.MALE,%0D%0A classification = Classification.STEER,%0D%0A colorMarkings = %22Black with white stripe%22,%0D%0A pastureId = pastureIds%5B3%5D, // West Lot%0D%0A status = Status.ACTIVE%0D%0A ),%0D%0A %0D%0A // Calves%0D%0A Cow(%0D%0A name = %22Buddy%22,%0D%0A tagNumber = %22K001%22,%0D%0A tagColor = %22Brown%22,%0D%0A birthDate = baseDate.plusMonths(3),%0D%0A gender = Gender.MALE,%0D%0A classification = Classification.CALF,%0D%0A colorMarkings = %22Brown and white spotted%22,%0D%0A motherId = 3, // Will be set after insertion%0D%0A fatherId = 1, // Will be set after insertion%0D%0A pastureId = pastureIds%5B0%5D, // North Field with mother%0D%0A status = Status.ACTIVE%0D%0A ),%0D%0A Cow(%0D%0A name = %22Bella%22,%0D%0A tagNumber = %22K002%22,%0D%0A tagColor = %22Black%22,%0D%0A birthDate = baseDate.plusMonths(1),%0D%0A gender = Gender.FEMALE,%0D%0A classification = Classification.CALF,%0D%0A colorMarkings = %22Solid black%22,%0D%0A motherId = 4, // Will be set after insertion%0D%0A fatherId = 2, // Will be set after insertion%0D%0A pastureId = pastureIds%5B0%5D, // North Field with mother%0D%0A status = Status.ACTIVE%0D%0A )%0D%0A )%0D%0A %0D%0A val cowIds = mutableListOf%3CLong%3E()%0D%0A cows.forEach %7B cow -%3E%0D%0A val id = insertCow(cow)%0D%0A cowIds.add(id)%0D%0A %7D%0D%0A %0D%0A // Update calf parent relationships with actual IDs%0D%0A if (cowIds.size %3E= 10) %7B%0D%0A val buddyId = cowIds%5B8%5D // Buddy%0D%0A val bellaId = cowIds%5B9%5D // Bella%0D%0A val bessieId = cowIds%5B2%5D // Bessie%0D%0A val daisyId = cowIds%5B3%5D // Daisy%0D%0A val thunderId = cowIds%5B0%5D // Thunder%0D%0A val stormId = cowIds%5B1%5D // Storm%0D%0A %0D%0A updateCow(getCowById(buddyId)!!.copy(motherId = bessieId, fatherId = thunderId))%0D%0A updateCow(getCowById(bellaId)!!.copy(motherId = daisyId, fatherId = stormId))%0D%0A %7D%0D%0A %0D%0A return cowIds%0D%0A %7D%0D%0A%0D%0A private suspend fun createSampleActivities(cowIds: List%3CLong%3E, pastureIds: List%3CString%3E) %7B%0D%0A val baseDate = LocalDate.now().minusMonths(6)%0D%0A %0D%0A // Sample move activities%0D%0A val moveGroupId = UUID.randomUUID().toString()%0D%0A insertActivity(Activity(%0D%0A cowId = cowIds%5B5%5D, // Luna%0D%0A date = baseDate.minusMonths(2),%0D%0A activityType = ActivityType.MOVED,%0D%0A fromPastureId = pastureIds%5B0%5D,%0D%0A toPastureId = pastureIds%5B1%5D,%0D%0A notes = %22Moved to better grazing area%22,%0D%0A groupId = moveGroupId%0D%0A ))%0D%0A %0D%0A // Sample weaning activity%0D%0A insertActivity(Activity(%0D%0A cowId = cowIds%5B8%5D, // Buddy%0D%0A date = baseDate.minusMonths(1),%0D%0A activityType = ActivityType.WEANED,%0D%0A notes = %22Weaned at 6 months old%22,%0D%0A groupId = UUID.randomUUID().toString()%0D%0A ))%0D%0A %0D%0A // Sample castration activity%0D%0A insertActivity(Activity(%0D%0A cowId = cowIds%5B7%5D, // Max (when he was a bull)%0D%0A date = baseDate.minusMonths(4),%0D%0A activityType = ActivityType.CASTRATED,%0D%0A notes = %22Castrated for beef production%22,%0D%0A groupId = UUID.randomUUID().toString()%0D%0A ))%0D%0A %0D%0A // Sample work activities%0D%0A insertActivity(Activity(%0D%0A cowId = cowIds%5B2%5D, // Bessie%0D%0A date = baseDate.minusWeeks(2),%0D%0A activityType = ActivityType.WORKED,%0D%0A notes = %22Vaccinated and health check%22,%0D%0A details = %22Annual vaccinations completed%22,%0D%0A groupId = UUID.randomUUID().toString()%0D%0A ))%0D%0A %0D%0A // Sample birth activity%0D%0A insertActivity(Activity(%0D%0A cowId = cowIds%5B9%5D, // Bella%0D%0A date = LocalDate.now().minusMonths(1),%0D%0A activityType = ActivityType.BIRTH,%0D%0A notes = %22Healthy female calf born%22,%0D%0A details = %22Birth weight: 75 lbs%22,%0D%0A groupId = UUID.randomUUID().toString()%0D%0A ))%0D%0A %7D%0D%0A%0D%0A private suspend fun createSampleNotes() %7B%0D%0A noteDao?.let %7B dao -%3E%0D%0A val notes = listOf(%0D%0A Note(%0D%0A title = %22Pasture Rotation Plan%22,%0D%0A text = %22Plan to rotate cattle between North Field and South Meadow every 3 months to prevent overgrazing and maintain grass health.%22,%0D%0A timestamp = System.currentTimeMillis() - (7 * 24 * 60 * 60 * 1000) // 7 days ago%0D%0A ),%0D%0A Note(%0D%0A title = %22Breeding Schedule%22,%0D%0A text = %22Thunder will be bred with Bessie and Daisy in spring. Storm will be bred with Rosie and Luna. Expecting calves in late winter/early spring.%22,%0D%0A timestamp = System.currentTimeMillis() - (3 * 24 * 60 * 60 * 1000) // 3 days ago%0D%0A ),%0D%0A Note(%0D%0A title = %22Feed Inventory%22,%0D%0A text = %22Current hay supply should last through winter. Need to order mineral supplements and check salt lick supplies in West Lot.%22,%0D%0A timestamp = System.currentTimeMillis() - (1 * 24 * 60 * 60 * 1000) // 1 day ago%0D%0A ),%0D%0A Note(%0D%0A title = %22Veterinary Visit%22,%0D%0A text = %22Dr. Johnson scheduled for next month to do annual health checks and vaccinations for the entire herd. Need to prepare holding area.%22,%0D%0A timestamp = System.currentTimeMillis() - (12 * 60 * 60 * 1000) // 12 hours ago%0D%0A )%0D%0A )%0D%0A %0D%0A notes.forEach %7B note -%3E%0D%0A dao.insert(note)%0D%0A %7D%0D%0A %7D%0D%0A %7D%0D%0A%0D%0A suspend fun deleteSampleData() %7B%0D%0A if (!isSampleDataInstalled()) return%0D%0A %0D%0A // Delete sample pastures (this will cascade to remove cows from these pastures)%0D%0A val samplePastureIds = listOf(%22sample-pasture-1%22, %22sample-pasture-2%22, %22sample-pasture-3%22, %22sample-pasture-4%22)%0D%0A samplePastureIds.forEach %7B pastureId -%3E%0D%0A getPastureById(pastureId)?.let %7B pasture -%3E%0D%0A deletePasture(pasture)%0D%0A %7D%0D%0A %7D%0D%0A %0D%0A // Delete sample cows (by tag number pattern)%0D%0A val sampleTagPrefixes = listOf(%22B00%22, %22C00%22, %22H00%22, %22S00%22, %22K00%22)%0D%0A val allCows = getAllCows().firstOrNull() ?: emptyList()%0D%0A allCows.filter %7B cow -%3E%0D%0A cow.tagNumber?.let %7B tag -%3E%0D%0A sampleTagPrefixes.any %7B prefix -%3E tag.startsWith(prefix) %7D%0D%0A %7D ?: false%0D%0A %7D.forEach %7B cow -%3E%0D%0A deleteCow(cow)%0D%0A %7D%0D%0A %0D%0A // Delete sample notes (by title pattern)%0D%0A noteDao?.let %7B dao -%3E%0D%0A val sampleNoteTitles = listOf(%22Pasture Rotation Plan%22, %22Breeding Schedule%22, %22Feed Inventory%22, %22Veterinary Visit%22)%0D%0A val allNotes = dao.getAllNotes().firstOrNull() ?: emptyList()%0D%0A allNotes.filter %7B note -%3E%0D%0A sampleNoteTitles.contains(note.title)%0D%0A %7D.forEach %7B note -%3E%0D%0A dao.delete(note)%0D%0A %7D%0D%0A %7D%0D%0A %0D%0A // Mark sample data as not installed%0D%0A insertOrUpdateSetting(%0D%0A Settings(%0D%0A SettingsKeys.SAMPLE_DATA_INSTALLED,%0D%0A %22false%22%0D%0A )%0D%0A )%0D%0A %7D%0D%0A%0D%0A suspend fun deleteAllData() %7B%0D%0A cowDao.deleteAllCows()%0D%0A pastureDao.deleteAllPastures()%0D%0A activityDao.deleteAllActivities()%0D%0A noteDao?.deleteAllNotes()%0D%0A %0D%0A // Reset sample data flag%0D%0A insertOrUpdateSetting(%0D%0A Settings(%0D%0A SettingsKeys.SAMPLE_DATA_INSTALLED,%0D%0A %22false%22%0D%0A )%0D%0A )%0D%0A %0D%0A // Reinitialize default data%0D%0A initializeDefaultData()%0D%0A %7D%0D
